DROP FUNCTION IF EXISTS cjams.routingive(objectid character varying, securityuserid character varying, appeventcode character varying, status integer, commenttext text, assignsecurityuserid character varying, bmanualrouting boolean, bclosecase boolean, bfromintake boolean, v_notifymsg character varying, v_routeddescription character varying, v_intakeserviceid character varying, v_intakeserreqstatustypeid character varying, userrole CHARACTER varying);
CREATE OR REPLACE FUNCTION cjams.routingive(objectid character varying, securityuserid character varying, appeventcode character varying, status integer, commenttext text, assignsecurityuserid character varying DEFAULT ''::character varying, bmanualrouting boolean DEFAULT false, bclosecase boolean DEFAULT false, bfromintake boolean DEFAULT false, v_notifymsg character varying DEFAULT ''::character varying, v_routeddescription character varying DEFAULT ''::character varying, v_intakeserviceid character varying DEFAULT ''::character varying, v_intakeserreqstatustypeid character varying DEFAULT ''::character varying, userrole CHARACTER varying DEFAULT ''::character varying, touserrole CHARACTER varying DEFAULT ''::character varying  )
 RETURNS text
 LANGUAGE plpgsql
AS $function$         

--------------------------------------------------------------
-- CIDM-8709 Gap Approval Section changes Veera 04-17-2024

--------------------------------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 /* One Parameter added decision - intakeserreqstatustypeid  */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 v_teamid uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 v_fromroleid character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 v_fromloadnumber character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_toroleid character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 v_securityuserid character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_objectid character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 v_status  character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 v_routingid uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 v_tosecurityusersid  character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 v_notifystatus character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 v_date timestamp without time zone;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_msg character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 v_username character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 v_assignsecurityuserid character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 v_taskstatus character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 v_dispositionstatusdescription text;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 v_dispositionstatusdesc text;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 v_tmpstatus integer;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 v_updateplacement character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 v_toroleid_ive character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 v_routingStatusId integer;
 v_insertrecordcount integer;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 v_torolekey character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 v_servicerequestno character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 v_servicerequestnumber character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 v_icjsecurityusersid uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 v_dispositionupdate    Character    varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 v_tousersid character varying;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 v_msgs character varying; 
 v_statuskey character varying;
 v_caseworkerid character varying;
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 v_assignsecurityuserid:= assignsecurityuserid;
 v_toroleid := touserrole;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 v_securityuserid:= securityuserid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 v_objectid:= objectid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 RAISE NOTICE 'status:%', status;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 v_date:= now();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 v_torolekey := '';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 v_servicerequestno:='';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 v_servicerequestnumber:='';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 v_dispositionstatusdesc:='';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 v_dispositionstatusdescription:='';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 select ISRST.description,servicerequestnumber into v_dispositionstatusdescription,v_servicerequestno  from intakeservicerequest as ISR                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
       join intakeserreqstatustype as ISRST on ISRST.intakeserreqstatustypeid = ISR.intakeserreqstatustypeid and ISRST.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 where ISR.activeflag =1 and ISR.intakenumber = v_objectid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 /* Get case number implemented by Gavaskar 11-01-2019  */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 select  ISR.servicerequestnumber into v_servicerequestnumber from intakeservicerequest as ISR                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
       join intakeserreqstatustype as ISRST on ISRST.intakeserreqstatustypeid = ISR.intakeserreqstatustypeid and ISRST.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 where ISR.activeflag =1 and ISR.intakeserviceid::character varying = v_objectid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 RAISE NOTICE 'v_servicerequestnumber:%', v_servicerequestnumber;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 RAISE NOTICE 'v_intakeserreqstatustypeid:%', v_intakeserreqstatustypeid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 /* Get Status disposition implemented by Gavaskar 11-01-2019  */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 if(appeventcode != 'IVEADOP')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 IF (coalesce(v_intakeserreqstatustypeid,'') <> '') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 select ISRST.description into v_dispositionstatusdesc from intakeserreqstatustype as ISRST where ISRST.intakeserreqstatustypeid::character varying = v_intakeserreqstatustypeid;                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 RAISE NOTICE 'v_intakeserviceid first :%', v_intakeserviceid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 if (coalesce(v_intakeserviceid,'') = '') THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
  v_intakeserviceid = v_objectid; END IF ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 SELECT servicerequestnumber into v_servicerequestno FROM intakeservicerequest                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 WHERE intakeserviceid :: character varying = v_intakeserviceid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 if(appeventcode = 'IVEADOP')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
 then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
 select servicecasenumber into v_servicerequestno  from servicecase where servicecaseid= v_intakeserviceid :: uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 RAISE NOTICE 'v_intakeserviceid aaa :%', v_intakeserviceid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
 RAISE NOTICE 'v_servicerequestno aa :%', v_servicerequestno;  

 SELECT  tm.teamid ,tm.loadnumber ,tm.roletypekey into                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 v_teamid,v_fromloadnumber,v_fromroleid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         FROM    teammemberassignment tma                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
         INNER JOIN  teammember tm                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 ON tm.teammemberid = tma.teammemberid AND tm.activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
         WHERE  tma.SecurityUsersId = v_securityuserid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         AND   tma.activeflag =1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 if (status in (39)) then  /*request  - assigned by role */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
         RAISE NOTICE 'inside:%', status;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
        SELECT routingid into v_routingid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         FROM routing r WHERE tosecurityusersid = v_securityuserid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
         AND activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         AND r.objectid  = v_objectid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
         AND r.eventcode = appeventcode                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         ORDER BY insertedon desc limit 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         UPDATE routing SET activeflag =0 ,remarks =commenttext,updatedon= v_date                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
         WHERE routingid = v_routingid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
             INSERT INTO routing(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                         eventcode, fromsecurityusersid, tosecurityusersid, teamid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                         fromroleid, toroleid,objectid , routingstatustypeid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                         insertedby,  updatedby,insertedon,updatedon, isreviewrequest,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                          remarks,routeddescription,servicerequestnumber)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
             SELECT rc.eventcode, v_securityuserid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                    'f876f968-fd45-4df5-ad3e-2973f3c1a702'   , tm.teamid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                     v_fromroleid, tm.roletypekey  ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                     v_objectid,status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                     v_securityuserid,v_securityuserid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                     v_date,v_date,true,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                     commenttext,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                     v_routeddescription,v_servicerequestno                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
              FROM teammemberassignment tma                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
              INNER join teammember tm                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 ON tm.teammemberid = tma.teammemberid  AND tm.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
              INNER join teammemberroletype  tmrt                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 ON tmrt.roletypekey = tm.roletypekey  AND tmrt.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
             INNER join userprofile up                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 ON up.securityusersid = tma.securityusersid AND up.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
             INNER join routingcONfig rc                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 ON rc.targetrolekey = tm.roletypekey   AND rc.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 and rc.sourcerolekey =v_fromroleid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             WHERE rc.eventcode =appeventcode AND tm.teamid =v_teamid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
             AND tma.activeflag =1 and coalesce(tm.isdefaultroute,0) =1 limit 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
             RETURNING tosecurityusersid INTO v_tosecurityusersid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 --           update tb_provider_complaint set complaint_status=status                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 --          where complaint_number=objectid and activeflag=1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           v_msg:=  v_notifymsg || ' by ';  /* Write off request ends */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
           v_status:='SUCCESS';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 --for diff team assignment                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 if (status in (67,68,69)) then  /*request  - Adoption Approvel */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
         RAISE NOTICE 'inside 145:%', status;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
        SELECT routingid into v_routingid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         FROM routing r WHERE r.objectid  = v_objectid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
         AND activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         AND r.eventcode = appeventcode                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         ORDER BY insertedon desc limit 1;    

         RAISE NOTICE 'inside 153:%', v_routingid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         UPDATE routing SET activeflag =0 --,remarks =commenttext                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
         ,updatedon= v_date                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
         WHERE routingid = v_routingid;   

         if (userrole != '')  then v_fromroleid := userrole;  end if;    

            Select COUNT(*) INTO v_insertrecordcount  
            FROM teammemberassignment tma                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
              INNER join teammember tm                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 ON tm.teammemberid = tma.teammemberid  AND tm.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
              INNER join teammemberroletype  tmrt                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 ON tmrt.roletypekey = tm.roletypekey  AND tmrt.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
             INNER join userprofile up                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 ON up.securityusersid = tma.securityusersid AND up.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
             INNER join routingcONfig rc                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 ON rc.targetrolekey = tm.roletypekey   AND rc.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 and rc.sourcerolekey =v_fromroleid   
                 and rc.targetrolekey =v_toroleid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             WHERE rc.eventcode =appeventcode -- AND tm.teamid =v_teamid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
             AND tma.activeflag =1 and  tma.SecurityUsersId = cast(v_assignsecurityuserid as character varying); 


        RAISE NOTICE 'inside 175:%', v_insertrecordcount; 
        IF v_insertrecordcount > 0 THEN   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
             INSERT INTO routing(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                         eventcode, fromsecurityusersid, tosecurityusersid, teamid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                         fromroleid, toroleid,objectid , routingstatustypeid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                         insertedby,  updatedby,insertedon,updatedon, isreviewrequest,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                          remarks,routeddescription,servicerequestnumber)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
             SELECT rc.eventcode, v_securityuserid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                     tma.SecurityUsersId   , tm.teamid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                     v_fromroleid, tm.roletypekey  ,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                     v_objectid,status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                     v_securityuserid,v_securityuserid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                     v_date,v_date,true,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                     commenttext,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                     v_routeddescription,v_servicerequestno                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
              FROM teammemberassignment tma                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
              INNER join teammember tm                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 ON tm.teammemberid = tma.teammemberid  AND tm.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
              INNER join teammemberroletype  tmrt                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 ON tmrt.roletypekey = tm.roletypekey  AND tmrt.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
             INNER join userprofile up                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 ON up.securityusersid = tma.securityusersid AND up.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
             INNER join routingcONfig rc                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 ON rc.targetrolekey = tm.roletypekey   AND rc.activeflag= 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 and rc.sourcerolekey =v_fromroleid   
                 and rc.targetrolekey =v_toroleid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
             WHERE rc.eventcode =appeventcode -- AND tm.teamid =v_teamid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
             AND tma.activeflag =1 and  tma.SecurityUsersId = cast(v_assignsecurityuserid as character varying)  limit 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
              v_tosecurityusersid:=cast(v_assignsecurityuserid as character varying) ;   

         ELSE 

           RAISE NOTICE 'inside 208:%', v_insertrecordcount; 
      
          INSERT INTO routing(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                         eventcode, fromsecurityusersid, tosecurityusersid, teamid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                         fromroleid, toroleid,objectid , routingstatustypeid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                         insertedby,  updatedby,insertedon,updatedon, isreviewrequest,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                          remarks,routeddescription,servicerequestnumber)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
             select distinct appeventcode, v_securityuserid,
              up.securityusersid, up.teamid, v_fromroleid,case when pg.permissiongroupname = 'IV-E Specialist, IV-E' then 'IVESP' when pg.permissiongroupname = 'IV-E Eligibility Analyst' then 'IVEEA' when pg.permissiongroupname = 'IV-E Eligibility Quality Assurance' then 'IVEQA' when pg.permissiongroupname = 'IV-E Eligibility Administrator' then 'IVEADMIN' else  'IVESV' end
             ,v_objectid, status, v_securityuserid,v_securityuserid, v_date,v_date,true,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
             commenttext, v_routeddescription,v_servicerequestno 
             from v_userprofile up
             inner join muser m on m.securityusersid= up.securityusersid
             inner join userresource ur on m.id = ur.userid
             inner join permissiongroup pg on ur.permissiongroupid = pg.permissiongroupid AND pg.activeflag = 1
             LEFT JOIN UserProfileAddress upa  ON upa.securityusersid = up.securityusersid AND upa.activeflag= 1
             where (case when v_toroleid = 'IVESP' then pg.permissiongroupname = 'IV-E Specialist, IV-E' when v_toroleid = 'IVEEA' then pg.permissiongroupname = 'IV-E Eligibility Analyst' 
            when v_toroleid = 'IVEQA' then pg.permissiongroupname = 'IV-E Eligibility Quality Assurance' when v_toroleid = 'IVEADMIN' then pg.permissiongroupname = 'IV-E Eligibility Administrator'
            when v_toroleid = 'IVESV' then pg.permissiongroupname = 'IV-E SUPERVISOR, IV-E' else pg.permissiongroupname in ('IV-E Specialist, IV-E', 'IV-E SUPERVISOR, IV-E', 'IV-E Eligibility Analyst',
            'IV-E Eligibility Administrator','IV-E Eligibility Quality Assurance') end)
             and up.securityusersid = cast(v_assignsecurityuserid as character varying) limit 1;
        End If;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 --           update tb_provider_complaint set complaint_status=status                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
