         AND activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         AND r.eventcode = appeventcode and routingstatustypeid= 73 and                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
         (v_toroleid_ive is null or r.toroleid in ('IVESP','IVEEA'))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
         ORDER BY insertedon desc limit 1;  

