         WHERE routingid = v_routingid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
             
        else if(status in (74))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
        then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         v_toroleid_ive := null;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
        v_routingStatusId := 73;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
        end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
       end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
      SELECT routingid into v_routingid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
