                 and rc.sourcerolekey =v_fromroleid   
                 and rc.targetrolekey = v_toroleid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
             WHERE rc.eventcode =appeventcode -- AND tm.teamid =v_teamid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
             AND tma.activeflag =1 and  tma.SecurityUsersId = cast(v_assignsecurityuserid as character varying)  limit 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
              v_tosecurityusersid:=cast(v_assignsecurityuserid as character varying) ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       

        ELSE 

        RAISE NOTICE 'v_securityuserid 480 new :%', v_fromroleid;  
          INSERT INTO routing(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                         eventcode, fromsecurityusersid, tosecurityusersid, teamid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                         fromroleid, toroleid,objectid , routingstatustypeid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                         insertedby,  updatedby,insertedon,updatedon, isreviewrequest,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                          remarks,routeddescription,servicerequestnumber)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
             select distinct appeventcode, v_securityuserid,
              up.securityusersid, up.teamid, userrole,case when pg.permissiongroupname = 'IV-E Specialist, IV-E' then 'IVESP' when pg.permissiongroupname = 'IV-E Eligibility Analyst' then 'IVEEA' when pg.permissiongroupname = 'IV-E Eligibility Quality Assurance' then 'IVEQA' when pg.permissiongroupname = 'IV-E Eligibility Administrator' then 'IVEADMIN' else  'IVESV' end
             ,v_objectid, status, v_securityuserid,v_securityuserid, v_date,v_date,true,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
             commenttext, v_routeddescription,v_servicerequestno 
             from v_userprofile up
             inner join muser m on m.securityusersid= up.securityusersid
             inner join userresource ur on m.id = ur.userid
             inner join permissiongroup pg on pg.permissiongroupid in ('2470c6ea-6b26-487b-a4f6-2ad6ee79c658','387da9aa-4deb-4054-8ab1-637c74bedad9','520c783d-e415-4f66-992b-e5e2fff35ad5','4a4be96e-a052-4fd1-8aab-381652fb92dd',
             '43ad59e1-6080-4341-83af-93ade093f385','ce664a6d-4233-496b-898b-11d080433dfd','7757acdb-974b-4202-b1d2-69a078fb27f0','a97c25a8-2449-4067-8709-f75ddc89f835',
             '8800a1c5-4eea-4d45-ad06-057be414fde9','9a29e0be-1506-4b30-a2c3-8b4ac0c8a1e0','a1cbfa86-6350-4f9a-a492-ddd9f82fa012') AND pg.activeflag = 1
             LEFT JOIN UserProfileAddress upa  ON upa.securityusersid = up.securityusersid  AND upa.activeflag= 1
             where (case when v_toroleid = 'IVESP' then pg.permissiongroupname = 'IV-E Specialist, IV-E' when v_toroleid = 'IVEEA' then pg.permissiongroupname = 'IV-E Eligibility Analyst' 
            when v_toroleid = 'IVEQA' then pg.permissiongroupname = 'IV-E Eligibility Quality Assurance' when v_toroleid = 'IVEADMIN' then pg.permissiongroupname = 'IV-E Eligibility Administrator'
            when v_toroleid = 'IVESV' then pg.permissiongroupname = 'IV-E SUPERVISOR, IV-E' else pg.permissiongroupname in ('IV-E Specialist, IV-E', 'IV-E SUPERVISOR, IV-E', 'IV-E Eligibility Analyst',
            'IV-E Eligibility Administrator','IV-E Eligibility Quality Assurance') end)
             and up.securityusersid = cast(v_assignsecurityuserid as character varying)  limit 1;
        End If;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
 --           update tb_provider_complaint set complaint_status=status                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
 --          where complaint_number=objectid and activeflag=1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           v_msg:=  v_notifymsg || ' by ';  /*  Adoption Approvel ends */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 v_status:='SUCCESS';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 if (status  in (75, 79)) then  /*approvel  - Write off approved by FS to FW */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
         RAISE NOTICE 'inside:%', status;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 RAISE NOTICE 'v_objectid:%', v_objectid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 RAISE NOTICE 'v_securityuserid:%', v_securityuserid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
          SELECT routingid,fromsecurityusersid into v_routingid,v_tosecurityusersid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             FROM routing r WHERE tosecurityusersid = v_securityuserid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
             AND activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             AND r.objectid  = v_objectid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
             ORDER BY insertedon desc limit 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
            RAISE NOTICE 'v_routingid:%', v_routingid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
             RAISE NOTICE 'v_tosecurityusersid:%', v_tosecurityusersid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
            UPDATE routing SET routingstatustypeid =status,remarks =commenttext,updatedon= v_date                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                 WHERE routingid = v_routingid and routingstatustypeid = 74;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           v_msg:=  v_notifymsg || ' by ';  /* Write off approvel */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_status:='SUCCESS';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 if (status  in (33,52,77, 80)) then  /*approvel  - Write off approved by FS to FW */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
         RAISE NOTICE 'inside:%', status;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 RAISE NOTICE 'v_objectid:%', v_objectid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
 RAISE NOTICE 'v_securityuserid:%', v_securityuserid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
          SELECT routingid,fromsecurityusersid into v_routingid,v_tosecurityusersid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
             FROM routing r WHERE tosecurityusersid = v_securityuserid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
             AND activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
             AND r.objectid  = v_objectid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
             ORDER BY insertedon desc limit 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
            RAISE NOTICE 'v_routingid:%', v_routingid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
             RAISE NOTICE 'v_tosecurityusersid:%', v_tosecurityusersid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
            UPDATE routing SET routingstatustypeid =status,remarks =commenttext,updatedon= v_date                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                 WHERE routingid = v_routingid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
           v_msg:=  v_notifymsg || ' by ';  /* Write off approvel */                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
 v_status:='SUCCESS';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
 IF (status in (72,75))then --send notification for cw supervisor                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 --select mu.securityusersid from team t join teammember tm on tm.teamid=t.teamid and tm.activeflag=1 join teammemberassignment tma on tma.teammemberid=tm.teammemberid and tma.activeflag=1 join muser mu on mu.securityusersid = tma.securityusersid and mu.activeflag=1                                                                                                                                                                                                                                                                                                                                                                   
 -- join rolemapping rm on rm.principalid::int=mu.id and rm.activeflag=1 join role r on r.id = rm.roleid :: int                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 -- where  r.roletypekey='IVESV'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 --        loop                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
         select rt.tosecurityusersid  into v_tousersid from routing rt where rt.routingstatustypeid =16 and rt.eventcode =appeventcode                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         and rt.toroleid ='CWCW' and rt.objectid= v_objectid limit 1 ;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
           SELECT COALESCE(lastname,'')||', '|| COALESCE(firstname,'')into v_username                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 FROM userprofile WHERE securityusersid = v_securityuserid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
           v_msg:=  v_notIFymsg || ' by ';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
           v_msgs:= COALESCE(v_msg ,'') ||COALESCE( v_username,'');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
          raise notice 'v_tousersid %',v_tousersid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                   SELECT send_notIFication INTO v_notIFystatus FROM send_notIFication( v_tousersid,v_securityuserid, v_tousersid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                 'System', 'High', v_msgs,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                  v_msgs , v_objectid);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
 --                               end loop;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
 end if; 
-- IVE case closure review start --
IF (status in (201,202,203,204,205)) then

select routingstatustypekey into v_statuskey 
	from routingstatustype where sequencenumber = status;  
                   
update ivecaseclosurereview set ivereviewstatus = v_statuskey, updatedon = v_date 
	where activeflag=1 and ivecaseclosurereviewid = v_objectid::uuid;
        
SELECT routingid into v_routingid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
	 FROM routing r WHERE activeflag =1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
	 AND r.objectid  = v_objectid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
	 AND r.eventcode = appeventcode                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
	 ORDER BY insertedon desc limit 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
 
UPDATE routing SET activeflag =0 ,remarks =commenttext,updatedon= v_date                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
     WHERE routingid = v_routingid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      

INSERT INTO routing(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
	             eventcode, fromsecurityusersid, tosecurityusersid, teamid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
	             fromroleid, toroleid,objectid , routingstatustypeid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
	             insertedby,  updatedby,insertedon,updatedon, isreviewrequest,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
              	 remarks,routeddescription,servicerequestnumber)
      VALUES(appeventcode, securityuserid, assignsecurityuserid, v_teamid,
     			v_fromroleid, v_toroleid, objectid, status,
     			securityuserid, securityuserid, v_date, v_date, true,
     			commenttext, v_routeddescription, null);
     		
	v_tosecurityusersid:= assignsecurityuserid;                                         
    
    select iccr.objectid, iccr.insertedby into v_objectid, v_caseworkerid from ivecaseclosurereview iccr where iccr.activeflag=1 and iccr.ivecaseclosurereviewid = v_objectid::uuid;
	-- notification to caseworker
   if(status in (204,205)) then
   
        SELECT COALESCE(lastname,'')||', '|| COALESCE(firstname,'')into v_username                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                    FROM userprofile WHERE securityusersid = securityuserid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
        v_msg:= COALESCE(v_notifymsg ,'')|| ' by ' ||COALESCE( v_username,''); 
    
        SELECT send_notIFication INTO v_notIFystatus FROM send_notIFication(v_caseworkerid, v_securityuserid, v_caseworkerid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                    'System', 'High', v_msg,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                    v_msg , v_objectid);
    end if;
    if(status in (203)) then
        v_msg:=  v_notifymsg;
        status:=0;
    else
	    v_msg:=  v_notifymsg || ' by ';
    end if;                                  
 end IF;         
-- IVE case closure review end --
         IF (status>0)then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
         SELECT COALESCE(lastname,'')||', '|| COALESCE(firstname,'')into v_username                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 FROM userprofile WHERE securityusersid = securityuserid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                 v_msg:= COALESCE(v_msg ,'') ||COALESCE( v_username,'');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                   SELECT send_notIFication INTO v_notIFystatus FROM send_notIFication(v_tosecurityusersid,v_securityuserid, v_tosecurityusersid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                 'System', 'High', v_msg,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                  v_msg , v_objectid);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                 --END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 RETURN v_status;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
 $function$
;
